//! Cargo-driven `setup.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_wmainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wmainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wmainCRTStartup"),
        o => panic!("setup-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["import:userenv", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "x86_64" => &["import:userenv", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "aarch64" => &["import:userenv", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/setup/setup",
        "base/setup/setup",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .c_from_compile_db("setup_shims", &["base/setup/setup/setup.c"])
        .rc("base/setup/setup/setup.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("dll/win32/userenv/userenv.spec", "userenv.dll", "userenv")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}
